/**
 * WooCommerce quantity-based percentage discounts.
 *
 * Adds a "Quantity Discounts" product-data tab where store managers can enter
 * minimum quantity + percentage discount rules, applies the best matching rule
 * in the cart, shows product-page price ranges, and exposes a price-breakdown
 * table with [tta_quantity_discounts].
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

if ( ! defined( 'TTA_QTY_DISCOUNT_META_KEY' ) ) {
    define( 'TTA_QTY_DISCOUNT_META_KEY', '_tta_quantity_discount_rules' );
}

/**
 * Return sanitized, sorted discount rules for a product.
 *
 * @param int $product_id Product ID.
 * @return array<int,array{min_qty:int,percent:float}>
 */
if ( ! function_exists( 'tta_get_quantity_discount_rules' ) ) {
function tta_get_quantity_discount_rules( $product_id ) {
    $rules = get_post_meta( $product_id, TTA_QTY_DISCOUNT_META_KEY, true );

    if ( ! is_array( $rules ) ) {
        return [];
    }

    $clean_rules = [];

    foreach ( $rules as $rule ) {
        if ( ! is_array( $rule ) ) {
            continue;
        }

        $min_qty = isset( $rule['min_qty'] ) ? absint( $rule['min_qty'] ) : 0;
        $percent = isset( $rule['percent'] ) ? (float) wc_format_decimal( $rule['percent'] ) : 0.0;

        if ( $min_qty < 1 || $percent <= 0 || $percent > 100 ) {
            continue;
        }

        $clean_rules[] = [
            'min_qty' => $min_qty,
            'percent' => $percent,
        ];
    }

    usort(
        $clean_rules,
        static function ( $a, $b ) {
            return $a['min_qty'] <=> $b['min_qty'];
        }
    );

    return $clean_rules;
}
}

/**
 * Pick the largest discount whose minimum quantity has been met.
 *
 * @param array<int,array{min_qty:int,percent:float}> $rules Rules.
 * @param int                                           $quantity Cart quantity.
 * @return array{min_qty:int,percent:float}|null
 */
if ( ! function_exists( 'tta_get_matching_quantity_discount_rule' ) ) {
function tta_get_matching_quantity_discount_rule( array $rules, $quantity ) {
    $matching_rule = null;

    foreach ( $rules as $rule ) {
        if ( $quantity >= $rule['min_qty'] ) {
            $matching_rule = $rule;
        }
    }

    return $matching_rule;
}
}

/**
 * Get the highest configured percentage discount for product-page ranges.
 *
 * @param int $product_id Product ID.
 * @return float
 */
if ( ! function_exists( 'tta_get_highest_quantity_discount_percent' ) ) {
function tta_get_highest_quantity_discount_percent( $product_id ) {
    $highest_percent = 0.0;

    foreach ( tta_get_quantity_discount_rules( $product_id ) as $rule ) {
        $highest_percent = max( $highest_percent, (float) $rule['percent'] );
    }

    return $highest_percent;
}
}

/**
 * Return the current display-price bounds for a product or its variations.
 *
 * @param WC_Product $product Product object.
 * @return array{min:float,max:float}|null
 */
if ( ! function_exists( 'tta_get_product_display_price_bounds' ) ) {
function tta_get_product_display_price_bounds( $product ) {
    if ( ! $product instanceof WC_Product ) {
        return null;
    }

    if ( $product->is_type( 'variable' ) && method_exists( $product, 'get_variation_prices' ) ) {
        $variation_prices = $product->get_variation_prices( true );
        $prices           = isset( $variation_prices['price'] ) && is_array( $variation_prices['price'] ) ? array_filter( array_map( 'floatval', $variation_prices['price'] ) ) : [];

        if ( empty( $prices ) ) {
            return null;
        }

        return [
            'min' => min( $prices ),
            'max' => max( $prices ),
        ];
    }

    $display_price = (float) wc_get_price_to_display( $product );

    if ( $display_price < 0 ) {
        return null;
    }

    return [
        'min' => $display_price,
        'max' => $display_price,
    ];
}
}

/**
 * Format one price or a low-to-high price range.
 *
 * @param float $minimum_price Minimum price.
 * @param float $maximum_price Maximum price.
 * @return string
 */
if ( ! function_exists( 'tta_format_quantity_discount_price_range' ) ) {
function tta_format_quantity_discount_price_range( $minimum_price, $maximum_price ) {
    $minimum_price = max( 0, (float) $minimum_price );
    $maximum_price = max( 0, (float) $maximum_price );

    if ( abs( $minimum_price - $maximum_price ) < 0.01 ) {
        return wc_price( $minimum_price );
    }

    return wc_format_price_range( $minimum_price, $maximum_price );
}
}

/**
 * Build price-breakdown rows for a product.
 *
 * @param int $product_id Product ID.
 * @return array<int,array{min_qty:int,percent:float,price_html:string}>
 */
if ( ! function_exists( 'tta_get_quantity_discount_price_rows' ) ) {
function tta_get_quantity_discount_price_rows( $product_id ) {
    $product = wc_get_product( $product_id );
    $bounds  = tta_get_product_display_price_bounds( $product );

    if ( ! $product || ! $bounds ) {
        return [];
    }

    $rows = [
        [
            'min_qty'    => 1,
            'percent'    => 0.0,
            'price_html' => tta_format_quantity_discount_price_range( $bounds['min'], $bounds['max'] ),
        ],
    ];

    foreach ( tta_get_quantity_discount_rules( $product_id ) as $rule ) {
        $discount_multiplier = 1 - ( (float) $rule['percent'] / 100 );

        $rows[] = [
            'min_qty'    => (int) $rule['min_qty'],
            'percent'    => (float) $rule['percent'],
            'price_html' => tta_format_quantity_discount_price_range( $bounds['min'] * $discount_multiplier, $bounds['max'] * $discount_multiplier ),
        ];
    }

    return $rows;
}
}

/**
 * Render a product's quantity price-breakdown table.
 *
 * @param int   $product_id Product ID.
 * @param array $args Render arguments.
 * @return string
 */
if ( ! function_exists( 'tta_get_quantity_discount_table_html' ) ) {
function tta_get_quantity_discount_table_html( $product_id, array $args = [] ) {
    $args = wp_parse_args(
        $args,
        [
            'title' => __( 'Price breakdown', 'tta' ),
            'empty' => '',
        ]
    );

    $rules = tta_get_quantity_discount_rules( $product_id );

    if ( empty( $rules ) ) {
        return wp_kses_post( $args['empty'] );
    }

    $rows = tta_get_quantity_discount_price_rows( $product_id );

    if ( empty( $rows ) ) {
        return wp_kses_post( $args['empty'] );
    }

    ob_start();
    ?>
    <div class="tta-quantity-discounts">
        <?php if ( '' !== $args['title'] ) : ?>
            <h3 class="tta-quantity-discounts__title"><?php echo esc_html( $args['title'] ); ?></h3>
        <?php endif; ?>

        <table class="shop_table tta-quantity-discounts__table">
            <thead>
                <tr>
                    <th><?php esc_html_e( 'Quantity', 'tta' ); ?></th>
                    <th><?php esc_html_e( 'Discount', 'tta' ); ?></th>
                    <th><?php esc_html_e( 'Unit price', 'tta' ); ?></th>
                </tr>
            </thead>
            <tbody>
                <?php foreach ( $rows as $row ) : ?>
                    <tr>
                        <td><?php echo esc_html( sprintf( __( '%d+', 'tta' ), $row['min_qty'] ) ); ?></td>
                        <td>
                            <?php
                            echo 0 < $row['percent']
                                ? esc_html( sprintf( __( '%s%% off', 'tta' ), wc_format_decimal( $row['percent'], 2 ) ) )
                                : esc_html__( 'Base price', 'tta' );
                            ?>
                        </td>
                        <td><?php echo wp_kses_post( $row['price_html'] ); ?></td>
                    </tr>
                <?php endforeach; ?>
            </tbody>
        </table>
    </div>
    <?php

    return ob_get_clean();
}
}

add_filter( 'woocommerce_product_data_tabs', function ( $tabs ) {
    $tabs['tta_quantity_discounts'] = [
        'label'    => __( 'Quantity Discounts', 'tta' ),
        'target'   => 'tta_quantity_discounts_product_data',
        'class'    => [ 'show_if_simple', 'show_if_variable' ],
        'priority' => 75,
    ];

    return $tabs;
} );

add_action( 'woocommerce_product_data_panels', function () {
    global $post;

    $rules = $post instanceof WP_Post ? tta_get_quantity_discount_rules( $post->ID ) : [];
    ?>
    <div id="tta_quantity_discounts_product_data" class="panel woocommerce_options_panel hidden">
        <div class="options_group">
            <?php wp_nonce_field( 'tta_save_quantity_discount_rules', 'tta_quantity_discount_rules_nonce' ); ?>
            <p class="form-field">
                <label><?php esc_html_e( 'Discount rules', 'tta' ); ?></label>
                <span class="description">
                    <?php esc_html_e( 'Enter quantity breakpoints and percentage discounts. The cart uses the highest qualifying rule for each product line.', 'tta' ); ?>
                </span>
            </p>

            <table class="widefat striped" id="tta-quantity-discount-rules" style="max-width: 720px; margin: 0 12px 12px;">
                <thead>
                    <tr>
                        <th><?php esc_html_e( 'Minimum quantity', 'tta' ); ?></th>
                        <th><?php esc_html_e( 'Discount (%)', 'tta' ); ?></th>
                        <th class="tta-rule-actions"><?php esc_html_e( 'Remove', 'tta' ); ?></th>
                    </tr>
                </thead>
                <tbody>
                    <?php if ( empty( $rules ) ) : ?>
                        <tr>
                            <td><input type="number" min="1" step="1" name="tta_quantity_discount_rules[0][min_qty]" value="" placeholder="12" /></td>
                            <td><input type="number" min="0.01" max="100" step="0.01" name="tta_quantity_discount_rules[0][percent]" value="" placeholder="10" /></td>
                            <td><button type="button" class="button tta-remove-quantity-discount-rule"><?php esc_html_e( 'Remove', 'tta' ); ?></button></td>
                        </tr>
                    <?php else : ?>
                        <?php foreach ( $rules as $index => $rule ) : ?>
                            <tr>
                                <td><input type="number" min="1" step="1" name="tta_quantity_discount_rules[<?php echo esc_attr( (string) $index ); ?>][min_qty]" value="<?php echo esc_attr( (string) $rule['min_qty'] ); ?>" /></td>
                                <td><input type="number" min="0.01" max="100" step="0.01" name="tta_quantity_discount_rules[<?php echo esc_attr( (string) $index ); ?>][percent]" value="<?php echo esc_attr( wc_format_localized_decimal( $rule['percent'] ) ); ?>" /></td>
                                <td><button type="button" class="button tta-remove-quantity-discount-rule"><?php esc_html_e( 'Remove', 'tta' ); ?></button></td>
                            </tr>
                        <?php endforeach; ?>
                    <?php endif; ?>
                </tbody>
            </table>

            <p class="form-field">
                <button type="button" class="button" id="tta-add-quantity-discount-rule"><?php esc_html_e( 'Add discount rule', 'tta' ); ?></button>
            </p>
        </div>
    </div>

    <script>
    jQuery(function ($) {
        const $table = $('#tta-quantity-discount-rules tbody');
        const rowTemplate = function (index) {
            return '<tr>' +
                '<td><input type="number" min="1" step="1" name="tta_quantity_discount_rules[' + index + '][min_qty]" value="" placeholder="12" /></td>' +
                '<td><input type="number" min="0.01" max="100" step="0.01" name="tta_quantity_discount_rules[' + index + '][percent]" value="" placeholder="10" /></td>' +
                '<td><button type="button" class="button tta-remove-quantity-discount-rule"><?php echo esc_js( __( 'Remove', 'tta' ) ); ?></button></td>' +
                '</tr>';
        };

        $('#tta-add-quantity-discount-rule').on('click', function () {
            $table.append(rowTemplate(Date.now()));
        });

        $table.on('click', '.tta-remove-quantity-discount-rule', function () {
            $(this).closest('tr').remove();
        });
    });
    </script>
    <?php
} );

add_action( 'woocommerce_admin_process_product_object', function ( $product ) {
    if ( ! $product instanceof WC_Product ) {
        return;
    }

    if (
        empty( $_POST['tta_quantity_discount_rules_nonce'] )
        || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['tta_quantity_discount_rules_nonce'] ) ), 'tta_save_quantity_discount_rules' )
    ) {
        return;
    }

    $posted_rules = isset( $_POST['tta_quantity_discount_rules'] ) && is_array( $_POST['tta_quantity_discount_rules'] )
        ? wc_clean( wp_unslash( $_POST['tta_quantity_discount_rules'] ) )
        : [];

    $clean_rules = [];

    foreach ( $posted_rules as $posted_rule ) {
        if ( ! is_array( $posted_rule ) ) {
            continue;
        }

        $min_qty = isset( $posted_rule['min_qty'] ) ? absint( $posted_rule['min_qty'] ) : 0;
        $percent = isset( $posted_rule['percent'] ) ? (float) wc_format_decimal( $posted_rule['percent'] ) : 0.0;

        if ( $min_qty < 1 || $percent <= 0 || $percent > 100 ) {
            continue;
        }

        $clean_rules[] = [
            'min_qty' => $min_qty,
            'percent' => $percent,
        ];
    }

    usort(
        $clean_rules,
        static function ( $a, $b ) {
            return $a['min_qty'] <=> $b['min_qty'];
        }
    );

    if ( empty( $clean_rules ) ) {
        $product->delete_meta_data( TTA_QTY_DISCOUNT_META_KEY );
    } else {
        $product->update_meta_data( TTA_QTY_DISCOUNT_META_KEY, $clean_rules );
    }
} );

add_action( 'woocommerce_before_calculate_totals', function ( $cart ) {
    if ( is_admin() && ! wp_doing_ajax() ) {
        return;
    }

    if ( ! $cart instanceof WC_Cart ) {
        return;
    }

    foreach ( $cart->get_cart() as $cart_item_key => $cart_item ) {
        if ( empty( $cart_item['data'] ) || ! $cart_item['data'] instanceof WC_Product ) {
            continue;
        }

        $product_id = ! empty( $cart_item['product_id'] ) ? absint( $cart_item['product_id'] ) : $cart_item['data']->get_id();
        $rules      = tta_get_quantity_discount_rules( $product_id );
        $quantity   = ! empty( $cart_item['quantity'] ) ? absint( $cart_item['quantity'] ) : 0;
        $rule       = tta_get_matching_quantity_discount_rule( $rules, $quantity );

        if ( ! isset( $cart->cart_contents[ $cart_item_key ]['tta_qty_discount_original_price'] ) ) {
            $cart->cart_contents[ $cart_item_key ]['tta_qty_discount_original_price'] = (float) $cart_item['data']->get_price( 'edit' );
        }

        $original_price = (float) $cart->cart_contents[ $cart_item_key ]['tta_qty_discount_original_price'];

        if ( ! $rule ) {
            $cart_item['data']->set_price( $original_price );
            unset( $cart->cart_contents[ $cart_item_key ]['tta_qty_discount_percent'] );
            continue;
        }

        $discounted_price = round( $original_price * ( 1 - ( $rule['percent'] / 100 ) ), wc_get_price_decimals() );

        $cart_item['data']->set_price( max( 0, $discounted_price ) );
        $cart->cart_contents[ $cart_item_key ]['tta_qty_discount_percent'] = $rule['percent'];
    }
}, 20 );

add_filter( 'woocommerce_get_item_data', function ( $item_data, $cart_item ) {
    if ( empty( $cart_item['tta_qty_discount_percent'] ) ) {
        return $item_data;
    }

    $item_data[] = [
        'name'  => __( 'Quantity discount', 'tta' ),
        'value' => sprintf(
            /* translators: %s: discount percentage. */
            __( '%s%% off', 'tta' ),
            wc_format_decimal( $cart_item['tta_qty_discount_percent'], 2 )
        ),
    ];

    return $item_data;
}, 10, 2 );

add_filter( 'woocommerce_get_price_html', function ( $price_html, $product ) {
    if ( ! is_product() || ! $product instanceof WC_Product ) {
        return $price_html;
    }

    $queried_product_id = absint( get_queried_object_id() );
    $product_id         = $product->is_type( 'variation' ) ? $product->get_parent_id() : $product->get_id();

    if ( $queried_product_id !== $product_id ) {
        return $price_html;
    }

    $highest_percent = tta_get_highest_quantity_discount_percent( $product_id );

    if ( $highest_percent <= 0 ) {
        return $price_html;
    }

    $bounds = tta_get_product_display_price_bounds( $product );

    if ( ! $bounds ) {
        return $price_html;
    }

    $lowest_possible_price  = $bounds['min'] * ( 1 - ( $highest_percent / 100 ) );
    $highest_possible_price = $bounds['max'];
    $range_html             = tta_format_quantity_discount_price_range( $lowest_possible_price, $highest_possible_price );
    $suffix                 = $product->get_price_suffix();

    return $suffix ? $range_html . $suffix : $range_html;
}, 20, 2 );

add_action( 'woocommerce_single_product_summary', function () {
    global $product;

    if ( ! $product instanceof WC_Product ) {
        return;
    }

    echo tta_get_quantity_discount_table_html( // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
        $product->get_id(),
        [
            'title' => __( 'Price breakdown', 'tta' ),
            'empty' => '',
        ]
    );
}, 19 );

add_shortcode( 'tta_quantity_discounts', function ( $atts ) {
    $atts = shortcode_atts(
        [
            'product_id' => 0,
            'title'      => __( 'Price breakdown', 'tta' ),
            'empty'      => '',
        ],
        $atts,
        'tta_quantity_discounts'
    );

    $product_id = absint( $atts['product_id'] );

    if ( ! $product_id && is_product() ) {
        $product_id = get_the_ID();
    }

    if ( ! $product_id ) {
        return '';
    }

    return tta_get_quantity_discount_table_html(
        $product_id,
        [
            'title' => $atts['title'],
            'empty' => $atts['empty'],
        ]
    );
} );
